const now          = new Date();
const last24h      = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const last7d       = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
return {
  now:            now.toISOString(),
  last24h:        last24h.toISOString(),
  last7d:         last7d.toISOString(),
  start_of_month: startOfMonth.toISOString(),
  report_date:    now.toLocaleDateString('es-MX', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
};

const salesItems    = $('Consultar Ventas del Día').all().map(i => i.json).filter(s => s && s.id);
const clientItems   = $('Consultar Nuevos Clientes del Día').all().map(i => i.json).filter(c => c && c.id);
const sessionItems  = $('Consultar Sesiones del Día').all().map(i => i.json).filter(s => s && s.id);
const productItems  = $('Consultar Estado de Inventario').all().map(i => i.json).filter(p => p && p.id);
const dateInfo      = $('Calcular Rangos de Fechas').item.json;

const totalSales   = salesItems.length;
const totalClients = clientItems.length;

const sessionsByStatus = {};
sessionItems.forEach(item => {
  const status = item.status || 'unknown';
  sessionsByStatus[status] = (sessionsByStatus[status] || 0) + 1;
});

const pendingConfirmation = sessionsByStatus['waiting_business_confirmation'] || 0;
const waitingPayment      = sessionsByStatus['waiting_payment_evidence']      || 0;
const selectingPayment    = sessionsByStatus['select_payment']                || 0;
const browsingProducts    = sessionsByStatus['waiting_product_approval']      || 0;

const activeProducts     = productItems.length;
const lowStockProducts   = productItems.filter(p => parseInt(p.stock) <= 5 && parseInt(p.stock) > 0).length;
const outOfStockProducts = productItems.filter(p => parseInt(p.stock) === 0).length;

const sep = '━'.repeat(28);
const report = `📊 *REPORTE FINANCIERO Y OPERATIVO*\n${sep}\n` +
`📅 *Fecha:* ${dateInfo.today_str || 'Hoy'}\n\n` +
`💰 *Ventas Confirmadas:* ${totalSales}\n` +
`👥 *Nuevos Clientes:* ${totalClients}\n\n` +
`🔄 *Embudo de Compras:*\n` +
`• ⏳ Pagos por verificar: ${pendingConfirmation}\n` +
`• 📸 Esperando comprobante: ${waitingPayment}\n` +
`• 💳 Seleccionando pago: ${selectingPayment}\n` +
`• 🛍️ Explorando productos: ${browsingProducts}\n\n` +
`📦 *Inventario:*\n` +
`• Activos: ${activeProducts}\n` +
`• ⚠️ Stock Crítico (≤5): ${lowStockProducts}\n` +
`• ⛔ Sin Stock: ${outOfStockProducts}`;

const buttons = [
  { id: "tareas", title: "📋 Ver Pendientes" },
  { id: "ver inventario", title: "📦 Ver Inventario" },
  { id: "ver citas", title: "📅 Ver Citas" }
];

return {
  wa_number: ($('Calcular Rangos de Fechas').item.json.tenant ? $('Calcular Rangos de Fechas').item.json.tenant.number : ($json.tenant ? $json.tenant.number : ($json.wa_number || '521234567890'))),
  wa_message: report,
  buttons: buttons,
  phone_number_id: ($('Calcular Rangos de Fechas').item.json.tenant ? $('Calcular Rangos de Fechas').item.json.tenant.whatsapp_phone_number_id : ($json.tenant ? $json.tenant.whatsapp_phone_number_id : ($json.phone_number_id || '10023456789'))),
  access_token: ($('Calcular Rangos de Fechas').item.json.tenant ? $('Calcular Rangos de Fechas').item.json.tenant.whatsapp_access_token : ($json.tenant ? $json.tenant.whatsapp_access_token : ($json.access_token || 'EAAG_DEMO_TOKEN')))
};
